doc.discount_amount = doc.custom_code_amount
doc.taxes = [tax for tax in doc.taxes if tax.account_head not in ["GST - OMG", "Shipping Income - OMG", "Discounts - OMG"]]

# 1. Add Custom VAT if available
if doc.custom_vat and doc.custom_vat > 0:
    doc.append("taxes", {
        "charge_type": "Actual",
        "account_head": "GST - OMG",
        "description": "Custom VAT",
        "tax_amount": doc.custom_vat
    })

# 2. Add Custom Shipping Cost if available
if doc.custom_shipping_cost and doc.custom_shipping_cost > 0:
    doc.append("taxes", {
        "charge_type": "Actual",
        "account_head": "Shipping Income - OMG",
        "description": "Shipping Cost",
        "tax_amount": doc.custom_shipping_cost,
        "cost_center": "Main - OMG"
    })

# 3. Add Custom Additional Discount (as negative)
if doc.custom_additional_discount_amount1 and doc.custom_additional_discount_amount1 > 0:
    doc.append("taxes", {
        "charge_type": "Actual",
        "account_head": "Discounts - OMG",
        "description": "Additional Discount",
        "cost_center": "Main - OMG",
        "tax_amount": -doc.custom_additional_discount_amount1
    })

doc.discount_amount = doc.custom_code_amount
doc.taxes = [tax for tax in doc.taxes if tax.account_head not in ["Shipping Income - OMG", "Discounts - OMG"]]

if doc.custom_shipping_cost and doc.custom_shipping_cost > 0:
    doc.append("taxes", {
        "charge_type": "Actual",
        "account_head": "Shipping Income - OMG",
        "description": "Shipping Cost",
        "cost_center": "Main - OMG",
        "tax_amount": doc.custom_shipping_cost
    })

if doc.custom_additional_discount_amount1 and doc.custom_additional_discount_amount1 > 0:
    doc.append("taxes", {
        "charge_type": "Actual",
        "account_head": "Discounts - OMG",
        "description": "Additional Discount",
        "cost_center": "Main - OMG",
        "tax_amount": -doc.custom_additional_discount_amount1
    })

doc = frappe.get_doc(doc)
if len(doc.transfer_expenses) > 1:
    frappe.throw(_("Not Allowed to add two lines in transfer expenses, delete all rows then add new row with total amount of expenses"))

if doc.transfer_expenses:
    accounts = []
    for d in doc.transfer_expenses:
        accounts.append({
            'account': d.expense_account,
            'debit_in_account_currency': abs(d.amount),
            'stock_entry': doc.name,
    	})
        accounts.append({
            'account': d.cash_account,
            'credit_in_account_currency': abs(d.amount)
        })
        journal_entry = frappe.get_doc({
            'doctype': 'Journal Entry',
            'company': doc.company,
            'posting_date': doc.posting_date,
            'accounts': accounts,
            'voucher_type': 'Cash Entry',
            'title': 'sample expenses for ' + doc.name,
            'user_remark': 'sample expenses for ' + doc.name
        }).insert()
        journal_entry.submit()
        frappe.db.set_value(d.doctype, d.name, "journal_voucher", journal_entry.name)
